// === Tab: RWalker ===
class RWalker {
	constructor(cx, cy, sze, op, bm, tl, ip) {
		this.cx = cx;
		this.cy = cy;
		this.sze = sze;
		this.ip = ip; // random() < 0.4; // is point / or lines
		this.op = op;
		this.bm = bm || BLEND;

		this.tl = tl; // timeline: array of objects {c: commands(grow, nop, del), f: frames}
		// init timeline
		this.ti = 0;  // timeline index
		this.tn = frameCount + this.tl[0].f; // frame with next command
		this.tc = this.tl[0].c; // current command

		// init vars
		this.init();
		// console.log(this)
	}

	updateTimeline() { // hacky command based timeline implementation
		if (this.tn !== frameCount) return; // frame with next command not reached

		this.ti = (this.ti + 1) % this.tl.length;  // increment timeline index
		this.tn = frameCount + this.tl[this.ti].f; // frame with next command
		this.tc = this.tl[this.ti].c; // current command
	}

	init() {
		// get a subset of the original palletes, num defines the symmetries also while drawing
	  this.ps = [];
		const numPal = ~~random(3, this.op.length);
		for (let i = 0; i < numPal; i++) {
	    this.ps.push(random(this.op))
  	}
		// init vars / depending on palette size
		this.lx = 0;
		this.ly = 0;
		this.alx = [];
		this.aly = [];
		for (let i = 0; i < this.ps.length; i++) {	
			this.alx[i] = 0;
			this.aly[i] = 0;
		}
		// reverse points lines
		this.ip = !this.ip;
	}

	show() {
		this.updateTimeline();

		// check timeline commands
		if (this.tc === "nop") {
			push();
			blendMode(BLEND);
			rectMode(CENTER);
			noStroke()
			fill(0, 16); // fade out
			rect(this.cx, this.cy, this.sze)
			pop();
			return;
		}
		if (this.tc === "del") {       // init vars and drawing area 
			push();
			blendMode(BLEND);
			rectMode(CENTER);
			noStroke()
			fill("black")
			rect(this.cx, this.cy, this.sze)
			pop();
			this.init();
			return;
		}

		push()
		blendMode(this.bm);
		translate(this.cx, this.cy)
		rotate(noise(this.cx, this.cy)*TWO_PI)
		const D = this.sze * 0.05;
		strokeWeight(D*0.25)
		const newX = constrain(this.lx + random(-D, D), -this.sze/2, this.sze/2);
		const newY = constrain(this.ly + random(-D, D), -this.sze/2, this.sze/2);
		const dltX = random(-D, D)
		const dltY = random(-D, D)

		// pline(this.lx, this.lx, newX, newY, this.ps);
	  const r = this.ps.length;
		for (let i = 0; i < r; i++) {
			push();
			rotate((i / r) * TWO_PI);
			stroke(this.ps[i][frameCount % this.ps[i].length]);
			let dx = random() > 0.42 ? 0 : random(-D/4, D/4);
			let dy = random() > 0.42 ? 0 : random(-D/4, D/4);
			let ndx = constrain(this.alx[i] + dltX + dx, -this.sze/2, this.sze/2);
			let ndy = constrain(this.aly[i] + dltY + dy, -this.sze/2, this.sze/2);
			// line(this.lx, this.ly, newX, newY);
			if (this.ip) {
				point(ndx, ndy);
			} else {			
				line(this.alx[i], this.aly[i], ndx, ndy);
			}
			this.alx[i] = ndx;
			this.aly[i] = ndy;
			pop();
		}

		this.lx = newX;
		this.ly = newY;

		pop();
	}
}

