/*
	Random Walker Grid #WCCChallenge Symmetries 1.4.24 
	#generativeart #creativecoding #p5js

  Dear Raph and creative coding community,

	implemented a random walker grid with a very hacky timeline definition
	to define if the walker shall go, just wait or the cell shall be start over.

	In every cell a random number of palettes defines also the number of rotation
	symmetries. A slightly deviation is implemented. Also a change between dot 
	and line visualization.

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let grid = []; // grid of RWalker

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S);
	describe("random walker 3x3 grid with random symmetric arms in each cell")
  frameRate(15);

	// define the grid
	const N = 3;
	grid = [];
	for (let y = 0; y < N; y++) {
		for (let x = 0; x < N; x++) {
			let blMode, tmLine, isPoint;
			if ((x+y)%2) { // every 2nd cell
				isPoint = true;
				blMode = BLEND;
				tmLine = [{c: "grow", f: 45}, {c: "nop", f: 29}, {c: "del", f: 1}];
			} else {				
				isPoint = false;
				blMode = ADD;
				tmLine = [{c: "nop", f: 29}, {c: "del", f: 1}, {c: "grow", f: 45}];
			}
			blMode = random([BLEND, ADD, DIFFERENCE, EXCLUSION, SCREEN])
			isPoint = false; // its fine, for 2nd case the "del" command switches status
			grid.push(new RWalker((x*2+1)*S/(2*N), (y*2+1)*S/(2*N), S/N, palettes, blMode, tmLine, isPoint))
		}		
	}

	background(0);
}

function draw() {
	// background(0, 12);
	for (let o of grid) {
		o.show();
	}
}

function mousePressed() {
  if (mouseButton === LEFT) setup();
}
